statement: -- 1. Restabelecer permissões de leitura/escrita no schema public
grant usage on schema public to postgres, anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to postgres, anon, authenticated, service_role;
grant usage, select on all sequences in schema public to postgres, anon, authenticated, service_role;
grant execute on all routines in schema public to postgres, anon, authenticated, service_role;

-- 2. Garantir vinculo do conector PostgREST (authenticator)
grant anon to authenticator;
grant authenticated to authenticator;
grant service_role to authenticator;

-- 3. Notificar a API para recarregar as conexões
notify pgrst, 'reload schema';
notify pgrst, 'reload config';


